// Typo fixes found by es_ES Hunspell + review, 19.10.26 (Maria). Exact replacements; guard: 'from' must occur exactly once in the live ES and last editor must be the automation account.
const MODE = 'write';
const AUTO = 'maria@efuturemedia.com';
const FIXES = [
 { id: 957278109, k: 'members-content::lessons::1668::steps:::2', from: 'Concis\u00f3n', to: 'Concisi\u00f3n' },
 { id: 957277971, k: 'members-content::lessons::1655::steps:::15', from: 'pensa en', to: 'piensa en' },
 { id: 957277948, k: 'members-content::lessons::1654::steps:::12', from: 'delegalo', to: 'del\u00e9galo' },
 { id: 957277633, k: 'members-content::lessons::1629::steps:::4', from: 'obligate a', to: 'obl\u00edgate a' },
 { id: 957278199, k: 'members-content::lessons::1676::steps:::2', from: 'analiz', to: 'analiz*' },
 { id: 957277788, k: 'members-content::lessons::1645::steps:::9', from: 'un puzzle', to: 'un puzle' },
 { id: 957279305, k: 'members-content::tests::1580::questions::10::answers::3', from: 'Transplante', to: 'Trasplante' },
 { id: 957277650, k: 'members-content::lessons::1631::steps:::5', from: 'los tests', to: 'los test' }
];
return [{ json: { mode: MODE, auto: AUTO, fixes: FIXES, ids: FIXES.map(function (f) { return f.id; }).join(',') } }];

const p = $('Plan').first().json;
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { throw new Error('Guard fetch failed: ' + JSON.stringify(b).slice(0, 200)); }
const live = {};
for (const k of b.keys) { for (const t of (k.translations || [])) { if (t.language_iso === 'es') { live[k.key_id] = { t: typeof t.translation === 'string' ? t.translation : '', by: t.modified_by_email || '', arch: k.is_archived }; } } }
const keys = []; const skipped = []; const done = [];
for (const f of p.fixes) {
  const L = live[f.id];
  if (!L || L.arch) { skipped.push({ k: f.k, why: 'missing/archived' }); continue; }
  if (L.by !== p.auto) { skipped.push({ k: f.k, why: 'last edited by ' + L.by }); continue; }
  const n = L.t.split(f.from).length - 1;
  if (n !== 1) { skipped.push({ k: f.k, why: 'from occurs ' + n + ' times' }); continue; }
  const nv = L.t.replace(f.from, f.to);
  keys.push({ key_id: f.id, translations: [{ language_iso: 'es', translation: nv, is_unverified: true }] });
  done.push(f.k + ': ' + f.from + ' -> ' + f.to);
}
if (p.mode !== 'write' || !keys.length) { return [{ json: { write: false, done: done, skipped: skipped } }]; }
return [{ json: { write: true, done: done, skipped: skipped, body: JSON.stringify({ keys: keys }) } }];

const p = $('Build PUT').first().json;
const r = $input.first().json; const b = r.body || {};
return [{ json: { write: p.write, status: r.statusCode, written: (b.keys || []).length, errors: b.errors || b.error || null, done: p.done, skipped: p.skipped } }];
